function changeStage(next){stage=next;dialog.dataset.stage=next;dialog.querySelectorAll('[data-stage]').forEach(el=>el.hidden=el.dataset.stage!==next);if(next==='hub'){cancelAnimationFrame(animationId);canvas.hidden=true;dialog.querySelector('.console-hub').scrollTop=0;}else{canvas.hidden=false;if(!reducedMotion.matches)startParticles();}dialog.scrollTop=0;window.dispatchEvent(new CustomEvent('portfolio:stage',{detail:{stage:next}}));}
function closeAdventure(){run++;clearTimeout(loadTimer);clearTimeout(bootTimer);cancelAnimationFrame(animationId);audio?.suspend().catch(()=>{});window.location.href='index.html';}
