async function beginLoading(){if(stage!=='welcome')return;changeStage('loading');$('#console-exit').focus({preventScroll:true});const currentRun=run,start=performance.now();let loaded=0,assetPercent=0;const assets=games.map(g=>g.image);const finished=Promise.all(assets.map(src=>new Promise(resolve=>{const im=new Image();let done=false;const settle=()=>{if(done)return;done=true;loaded++;assetPercent=loaded/assets.length;resolve()};im.onload=settle;im.onerror=settle;im.src=src;if(im.complete)settle();setTimeout(settle,5000)})));
 if(sound)playChime();
 const tick=()=>{if(run!==currentRun||!appActive||stage!=='loading')return;const elapsed=performance.now()-start,cinematic=reducedMotion.matches?1:Math.min(1,elapsed/2100);const p=Math.round(Math.min(100,Math.min(assetPercent,cinematic)*100));$('#console-progress-fill').style.width=p+'%';$('.console-progress').setAttribute('aria-valuenow',p);$('#console-progress-percent').textContent=p+'%';$('#console-load-copy').textContent=loaded===games.length?'Opening your collection':`Loading artwork · ${loaded} of ${games.length}`;if(p===100){loadTimer=setTimeout(()=>{if(run===currentRun&&stage==='loading')showLibrary()},200)}else loadTimer=setTimeout(tick,45)};tick();await finished;
}
